import {useEffect,useRef,useState,type FormEvent} from 'react';
import {ArrowLeft,ArrowRight,Check,CheckCircle2,ChevronRight,ClipboardList,Clock3,CreditCard,ExternalLink,FileText,Headphones,History,Mail,MessageCircle,Plus,Search,Settings2,ShieldCheck,UsersRound,X} from 'lucide-react';
import {api,money,zonedToISO} from './api';
import FormDialog from './FormDialog';
import {Empty,PageHeader} from './ui';
import {BusinessPagination,BusinessState,businessDate,centsInput,integerValue,parseCents,reasonText,useBusinessCommand,useBusinessQuery,type BusinessPageProps,type PageResult} from './businessUi';

type Plan={id:'monthly'|'yearly';name:string;amount_cents:number;interval_months:number;checkout_url:string|null;checkout_reviewed?:boolean;active?:boolean};
type Subscription={tenant_id:string;plan_id:string;status:'pending'|'trial'|'active'|'suspended'|'cancelled';trial_ends_at:string|null;paid_through:string|null;plan_name:string;amount_cents:number;interval_months:number;grace_days:number;access_until:string|null;writable:boolean;suspension_reason:string;trial_days?:number;trial_started_at?:string|null;onboarding_completed_at?:string|null;onboarding_plan?:'free'|'monthly'|'yearly'|null};
type SubscriptionPayment={id:string;plan_id:string;amount_cents:number;provider_reference:string;period_start:string;period_end:string;received_at:string;voided_at:string|null;void_reason?:string};
type SubscriptionData={subscription:Subscription;plans:Plan[];payments:SubscriptionPayment[];canManage:boolean;supportEmail:string|null;billingMode:string;trialDays?:number};
type Legal={published:boolean;version:string;effectiveDate:string|null;operator:{brand:string;legalName:string|null;supportEmail:string|null;privacyEmail:string|null;address:string|null};documents:{privacy:string;terms:string};subprocessors:Processor[]};
type Processor={name:string;purpose:string;location:string};
type PlatformSettings={brand:string;legal_name:string|null;support_email:string|null;privacy_email:string|null;address:string|null;privacy_text:string;terms_text:string;published:boolean;legal_version:string;effective_date:string|null;subprocessors:Processor[];trial_days:number;grace_days:number;plans:Plan[]};
type CompanySubscription={id:string;name:string;active:boolean;plan_id:string|null;status:string|null;trial_ends_at:string|null;paid_through:string|null;suspension_reason:string|null;amount_cents:number|null;plan_name:string|null};
type PlatformSubscription={company:{id:string;name:string;active:boolean};subscription:Subscription;payments:SubscriptionPayment[];plans:Plan[]};
type AuditEvent={id:string;tenant_id:string|null;actor_user_id:string|null;action:string;entity_type:string|null;entity_id:string|null;metadata:Record<string,unknown>;created_at:string};
type Ticket={id:string;tenant_id:string;subject:string;category:string;status:'open'|'in_progress'|'resolved';created_at:string;updated_at:string;company_name?:string};
type TicketData={ticket:Ticket;messages:{id:string;body:string;from_platform:boolean;created_at:string}[]};
const statuses:Record<string,string>={pending:'Pagamento pendente',trial:'Free · teste',active:'Ativa',suspended:'Suspensa',cancelled:'Cancelada',open:'Aberta',in_progress:'Em atendimento',resolved:'Resolvida'};
const categories:Record<string,string>={access:'Acesso',billing:'Assinatura e cobrança',technical:'Dúvida ou problema técnico',privacy:'Privacidade e dados pessoais',other:'Outro assunto'};
function Label({status}:{status:string}){return <span className={`commercial-label commercial-label--${status}`}>{statuses[status]??status}</span>;}
function wallNow(){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()).map(part=>[part.type,part.value]));return `${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}`;}
function safeCheckout(value:string|null|undefined){if(!value)return null;try{const url=new URL(value);return url.protocol==='https:'&&!url.username&&!url.password&&!url.port&&['pag.ae','pagbank.com.br','pagseguro.uol.com.br'].some(host=>url.hostname===host||host!=='pag.ae'&&url.hostname.endsWith('.'+host))?url.href:null;}catch{return null;}}
function PaymentHistory({payments,onVoid}:{payments:SubscriptionPayment[];onVoid?:(payment:SubscriptionPayment)=>void}){
  return payments.length?<div className="commercial-payments">{payments.map(payment=><article key={payment.id}><span className={`commercial-payment-symbol ${payment.voided_at?'is-void':''}`}><CreditCard size={19}/></span><div><strong>{money(payment.amount_cents)} · {payment.plan_id==='yearly'?'Anual':'Mensal'}</strong><span>{businessDate(payment.received_at,undefined,true)}</span><small>Período: {businessDate(payment.period_start)} a {businessDate(payment.period_end)}</small><small>Referência: {payment.provider_reference}</small>{payment.voided_at&&<small className="commercial-void-note">Registro invalidado em {businessDate(payment.voided_at)}{payment.void_reason?` · ${payment.void_reason}`:''}</small>}</div>{onVoid&&!payment.voided_at&&<button type="button" className="text-link commercial-danger-link" onClick={()=>onVoid(payment)}>Invalidar</button>}</article>)}</div>:<Empty label="Nenhum recebimento de assinatura registrado."/>;
}

export function SubscriptionPage({setMessage,setError}:BusinessPageProps){
  const query=useBusinessQuery<SubscriptionData>('/commercial/me',setError),[selecting,setSelecting]=useState<string|null>(null);
  async function choose(plan:Plan){if(selecting)return;setSelecting(plan.id);try{await api('/commercial/choose-plan','POST',{plan_id:plan.id});setMessage('Preferência de plano salva. O pagamento é realizado na página segura do PagBank.');query.refresh();}catch(cause){setError(reasonText(cause));}finally{setSelecting(null);}}
  const data=query.data,subscription=data?.subscription,grace=subscription&&subscription.writable&&subscription.access_until&&new Date(subscription.access_until).getTime()<Date.now();
  return <div className="commercial-page">
    <PageHeader eyebrow="PLANO E ASSINATURA" title="Seu PetCore" subtitle="Consulte seu período de acesso, escolha o plano e acompanhe os pagamentos."/>
    <BusinessState loading={query.loading} error={query.error} retry={query.refresh}>{subscription&&<>
      <section className={`commercial-subscription-summary ${!subscription.writable?'is-readonly':''}`}><span className="commercial-large-icon"><ShieldCheck size={29}/></span><div><div className="commercial-summary-heading"><h2>{subscription.status==='trial'&&!subscription.paid_through?'Plano Free':subscription.plan_name}</h2><Label status={subscription.status}/></div><p>{subscription.status==='trial'&&!subscription.paid_through?`Período gratuito de teste de ${data?.trialDays??subscription.trial_days??30} dias.`:'Assinatura para a gestão do seu pet shop.'}</p><dl><div><dt>{subscription.paid_through?'Pago até':subscription.status==='trial'?'Teste válido até':'Confirmação do pagamento'}</dt><dd>{subscription.paid_through||subscription.status==='trial'?businessDate(subscription.paid_through||subscription.trial_ends_at):'Aguardando recebimento'}</dd></div><div><dt>Situação do acesso</dt><dd>{!subscription.writable?'Somente consulta':grace?'Prazo para regularização':'Disponível para uso'}</dd></div></dl>{!subscription.writable&&<p className="commercial-access-note">Seus dados continuam disponíveis para consulta. Regularize a assinatura para voltar a cadastrar e alterar informações.</p>}{grace&&<p className="commercial-access-note">O período de acesso terminou. Você tem uma tolerância de {subscription.grace_days} dia(s) para regularizar o pagamento.</p>}{subscription.suspension_reason&&<p className="commercial-access-note">{subscription.suspension_reason}</p>}</div></section>
      <section aria-label="Planos do PetCore"><div className="commercial-section-title"><h2>Escolha como continuar</h2><p>O pagamento é feito no ambiente seguro do PagBank.</p></div><div className="commercial-plans">{data?.plans.map(plan=>{const ready=plan.checkout_reviewed===true&&Boolean(plan.checkout_url),selected=subscription.plan_id===plan.id;return <article className={`commercial-plan ${plan.id==='yearly'?'commercial-plan--annual':''}`} key={plan.id}>{plan.id==='yearly'&&<span className="commercial-plan-ribbon">Pagamento anual</span>}<span className="commercial-plan-icon"><CreditCard size={24}/></span><h3>{plan.name}</h3><p className="commercial-plan-price"><strong>{money(plan.amount_cents)}</strong><span>/{plan.interval_months===12?'ano':'mês'}</span></p>{plan.interval_months===12&&<p className="commercial-plan-equivalent">{money(Math.round(plan.amount_cents/12))} por mês, em um pagamento anual</p>}<ul><li><Check size={15}/>Gestão de agenda e clientes</li><li><Check size={15}/>CRM, financeiro e estoque</li><li><Check size={15}/>Relatórios e acesso da equipe</li></ul>{data.canManage?<><button className={selected?'ghost-btn':'primary-btn'} disabled={selecting!==null||selected} onClick={()=>void choose(plan)}>{selecting===plan.id?'Salvando...':selected?'Plano selecionado':'Selecionar plano'}</button>{ready?<a className="commercial-checkout-link" href={plan.checkout_url!} target="_blank" rel="noopener noreferrer">Pagar no PagBank <ExternalLink size={15}/></a>:<span className="commercial-checkout-unavailable">Pagamento indisponível no momento. Consulte o suporte.</span>}</>:<p className="commercial-plan-manager">O responsável pelo pet shop gerencia a assinatura.</p>}</article>;})}</div></section>
      <section className="panel commercial-panel"><div className="commercial-panel-head"><span className="commercial-panel-symbol"><Clock3 size={23}/></span><div><h2>Como funciona a confirmação</h2><p>Os dados do cartão ficam no PagBank.</p></div></div><ol className="commercial-steps"><li>O responsável escolhe o plano e realiza o pagamento no link do PagBank.</li><li>A cobrança recorrente é gerenciada pelo PagBank, conforme a autorização dada no pagamento.</li><li>A Tiger Tech confere o recebimento no painel do PagBank e atualiza a validade do PetCore.</li></ol><p className="commercial-small-note">Selecionar um plano aqui não cobra seu cartão. Se já possui uma assinatura recorrente, fale com o suporte antes de iniciar outra ou trocar o plano, para evitar cobranças duplicadas.</p></section>
      {data?.canManage&&<section className="panel commercial-panel"><div className="commercial-panel-head"><span className="commercial-panel-symbol"><History size={23}/></span><div><h2>Histórico de recebimentos</h2><p>Até 50 registros confirmados pela Tiger Tech.</p></div></div><PaymentHistory payments={data.payments}/></section>}
      <section className="panel commercial-panel"><h2>Ajuda com sua assinatura</h2><p className="commercial-body-copy">Para confirmar um pagamento, mudar o plano ou solicitar cancelamento, abra uma solicitação na área Suporte.{data?.supportEmail&&<> Você também pode escrever para <a href={`mailto:${data.supportEmail}`}>{data.supportEmail}</a>.</>}</p><p className="commercial-small-note">O cancelamento do acesso ao PetCore e o cancelamento da cobrança recorrente são ações diferentes. A Tiger Tech deve confirmar o encerramento da cobrança no PagBank. Não envie número de cartão, senha ou código de segurança pelo suporte.</p></section>
    </>}</BusinessState>
  </div>;
}

type PlatformDialog='company'|'receipt'|'void'|'status'|'settings'|'plan'|null;
type SettingsDraft={brand:string;legal_name:string;support_email:string;privacy_email:string;address:string;privacy_text:string;terms_text:string;published:boolean;effective_date:string;subprocessors:Processor[];trial_days:string;grace_days:string};
const emptySettings:SettingsDraft={brand:'Tiger Tech',legal_name:'',support_email:'',privacy_email:'',address:'',privacy_text:'',terms_text:'',published:false,effective_date:'',subprocessors:[],trial_days:'30',grace_days:'3'};

export function PlatformOperations({setMessage,setError}:BusinessPageProps){
  const [area,setArea]=useState<'subscriptions'|'settings'|'audit'|'support'>('subscriptions'),[search,setSearch]=useState(''),[query,setQuery]=useState(''),[page,setPage]=useState(1),[auditPage,setAuditPage]=useState(1);
  const config=useBusinessQuery<PlatformSettings>('/commercial/platform/settings',setError),subscriptions=useBusinessQuery<PageResult<CompanySubscription>>(`/commercial/platform/subscriptions?${new URLSearchParams({q:query,page:String(page),page_size:'20'})}`,setError),audit=useBusinessQuery<PageResult<AuditEvent>>(area==='audit'?`/commercial/audit?page=${auditPage}&page_size=20`:null,setError);
  const [dialog,setDialog]=useState<PlatformDialog>(null),[company,setCompany]=useState<CompanySubscription|null>(null),[payment,setPayment]=useState<SubscriptionPayment|null>(null),[plan,setPlan]=useState<Plan|null>(null),[busy,setBusy]=useState(false),[error,setLocalError]=useState('');
  const detail=useBusinessQuery<PlatformSubscription>(company&&['company','receipt','void','status'].includes(dialog??'')?`/commercial/platform/subscriptions/${company.id}`:null,setError);
  const [receiptPlan,setReceiptPlan]=useState<'monthly'|'yearly'>('monthly'),[reference,setReference]=useState(''),[receivedAt,setReceivedAt]=useState(wallNow),[confirmed,setConfirmed]=useState(false),[password,setPassword]=useState(''),[reason,setReason]=useState(''),[accessStatus,setAccessStatus]=useState<'active'|'suspended'>('suspended');
  const [draft,setDraft]=useState<SettingsDraft>(emptySettings),[settingsTab,setSettingsTab]=useState<'identity'|'documents'|'providers'|'access'>('identity'),[review,setReview]=useState(false);
  const [planName,setPlanName]=useState(''),[planAmount,setPlanAmount]=useState(''),[planUrl,setPlanUrl]=useState(''),[planActive,setPlanActive]=useState(true),[checkoutReviewed,setCheckoutReviewed]=useState(false);
  const command=useBusinessCommand(),mounted=useRef(true);
  useEffect(()=>{mounted.current=true;return()=>{mounted.current=false;};},[]);
  useEffect(()=>{const timer=setTimeout(()=>{setQuery(search.trim());setPage(1);},300);return()=>clearTimeout(timer);},[search]);
  function report(cause:unknown){const text=reasonText(cause);setLocalError(text);setError(text);}
  function reset(mode:PlatformDialog){command.reset();setLocalError('');setPassword('');setReason('');setDialog(mode);}
  function close(){if(!busy){setDialog(null);setCompany(null);setPayment(null);setPlan(null);setPassword('');setLocalError('');}}
  function companyBack(){if(!busy){setPassword('');setReason('');setLocalError('');setDialog('company');}}
  function openCompany(item:CompanySubscription){setCompany(item);reset('company');}
  function openReceipt(){setReceiptPlan((detail.data?.subscription.plan_id??'monthly') as 'monthly'|'yearly');setReference('');setReceivedAt(wallNow());setConfirmed(false);reset('receipt');}
  function openStatus(){setAccessStatus(detail.data?.subscription.status==='suspended'?'active':'suspended');reset('status');}
  function openSettings(){if(!config.data)return;const current=config.data;setDraft({brand:current.brand,legal_name:current.legal_name??'',support_email:current.support_email??'',privacy_email:current.privacy_email??'',address:current.address??'',privacy_text:current.privacy_text??'',terms_text:current.terms_text??'',published:current.published,effective_date:String(current.effective_date??'').slice(0,10),subprocessors:current.subprocessors.map(item=>({...item})),trial_days:String(current.trial_days),grace_days:String(current.grace_days)});setReview(false);setSettingsTab('identity');reset('settings');}
  function editPlan(item:Plan){setPlan(item);setPlanName(item.name);setPlanAmount(centsInput(item.amount_cents));setPlanUrl(item.checkout_url??'');setPlanActive(item.active!==false);setCheckoutReviewed(item.checkout_reviewed===true);reset('plan');}
  async function save(event:FormEvent){event.preventDefault();if(busy)return;setBusy(true);setLocalError('');try{
    if(dialog==='receipt'&&company){
      const selected=(detail.data?.plans??config.data?.plans)?.find(item=>item.id===receiptPlan);if(!selected)throw Error('Selecione um plano disponível.');if(!confirmed)throw Error('Confirme a conferência do recebimento no PagBank.');
      await command.send(`/commercial/platform/subscriptions/${company.id}/payments`,{plan_id:receiptPlan,amount_cents:selected.amount_cents,provider_reference:reference.trim(),received_at:zonedToISO(receivedAt,'America/Sao_Paulo'),confirmed_in_pagbank:true});
      if(!mounted.current)return;setMessage('Recebimento confirmado no PetCore e validade atualizada.');setDialog('company');detail.refresh();subscriptions.refresh();
    }else if(dialog==='void'&&payment){
      await api(`/commercial/platform/payments/${payment.id}/void`,'POST',{reason:reason.trim(),password});if(!mounted.current)return;setMessage('Registro invalidado. Um eventual estorno do cartão deve ser feito no PagBank.');setDialog('company');detail.refresh();subscriptions.refresh();
    }else if(dialog==='status'&&company){
      await api(`/commercial/platform/subscriptions/${company.id}/status`,'PATCH',{status:accessStatus,reason:reason.trim(),password});if(!mounted.current)return;setMessage('Situação de acesso atualizada.');setDialog('company');detail.refresh();subscriptions.refresh();
    }else if(dialog==='settings'){
      await api('/commercial/platform/settings','PUT',{...draft,effective_date:draft.effective_date||null,trial_days:integerValue(draft.trial_days,0,90),grace_days:integerValue(draft.grace_days,0,30),review_confirmed:review,...(password?{password}:{})});if(!mounted.current)return;setMessage(draft.published?'Documentos e configurações publicados na versão atualizada.':'Rascunho e configurações salvos.');setDialog(null);config.refresh();
    }else if(dialog==='plan'&&plan){
      await api(`/commercial/platform/plans/${plan.id}`,'PATCH',{name:planName.trim(),amount_cents:parseCents(planAmount),checkout_url:planUrl.trim()||null,active:planActive,checkout_reviewed:checkoutReviewed});if(!mounted.current)return;setMessage('Plano atualizado.');setDialog(null);config.refresh();
    }
    command.reset();setPassword('');audit.refresh();
  }catch(cause){if(mounted.current)report(cause);}finally{if(mounted.current)setBusy(false);}}
  const current=detail.data?.subscription,selectedReceiptPlan=(detail.data?.plans??config.data?.plans)?.find(item=>item.id===receiptPlan);
  const dialogTitle=dialog==='company'?company?.name??'Assinatura':dialog==='receipt'?'Confirmar recebimento':dialog==='void'?'Invalidar recebimento':dialog==='status'?'Alterar acesso':dialog==='settings'?'Configuração comercial':dialog==='plan'?`Editar ${plan?.name??'plano'}`:'';
  const footer=(label:string)=><div className="form-actions"><button type="button" className="ghost-btn" disabled={busy} onClick={['receipt','void','status'].includes(dialog??'')?companyBack:close}>Cancelar</button><button className={dialog==='void'?'danger-btn':'primary-btn'} type="submit" disabled={busy}>{busy?'Salvando...':label}</button></div>;
  function updateProcessor(index:number,field:keyof Processor,value:string){setDraft(previous=>({...previous,subprocessors:previous.subprocessors.map((item,i)=>i===index?{...item,[field]:value}:item)}));}
  return <section className="commercial-page commercial-operations">
    <div className="commercial-section-title"><h2>Operação da plataforma</h2><p>Assinaturas, documentos, atendimento e histórico de alterações.</p></div>
    <div className="commercial-tabs" role="group" aria-label="Operação da plataforma">{([['subscriptions','Assinaturas',CreditCard],['settings','Configuração',Settings2],['audit','Auditoria',ShieldCheck],['support','Suporte',Headphones]] as const).map(([key,label,Icon])=><button key={key} className={area===key?'selected':''} aria-pressed={area===key} onClick={()=>setArea(key)}><Icon size={17}/>{label}</button>)}</div>
    {area==='support'?<SupportPage setError={setError} setMessage={setMessage} platform/>:area==='subscriptions'?<section className="panel commercial-panel"><div className="commercial-panel-head"><div><h2>Assinaturas dos pet shops</h2><p>A validade é atualizada após a conferência do pagamento no PagBank.</p></div></div><label className="commercial-search"><Search size={18}/><span className="commercial-sr-only">Buscar empresa</span><input type="search" maxLength={100} value={search} onChange={event=>setSearch(event.target.value)} placeholder="Buscar nome da empresa"/></label><BusinessState loading={subscriptions.loading} error={subscriptions.error} retry={subscriptions.refresh} empty={!subscriptions.data?.items.length?'Nenhuma empresa encontrada.':undefined}><div className="commercial-company-list">{subscriptions.data?.items.map(item=><article key={item.id}><span className="commercial-company-symbol"><UsersRound size={21}/></span><div><strong>{item.name}</strong><small>{item.plan_name||'Free · período de teste'}{item.paid_through?` · Pago até ${businessDate(item.paid_through)}`:item.trial_ends_at?` · Teste até ${businessDate(item.trial_ends_at)}`:''}</small><Label status={item.status??'trial'}/></div><button className="ghost-btn" onClick={()=>openCompany(item)} aria-label={`Gerenciar assinatura de ${item.name}`}>Gerenciar <ChevronRight size={15}/></button></article>)}</div><BusinessPagination page={page} pageSize={subscriptions.data?.pageSize??20} total={subscriptions.data?.total??0} onPage={setPage}/></BusinessState></section>:area==='audit'?<section className="panel commercial-panel"><div className="commercial-panel-head"><div><h2>Histórico de auditoria</h2><p>Operações registradas com data, empresa e identificação do responsável.</p></div></div><BusinessState loading={audit.loading} error={audit.error} retry={audit.refresh} empty={!audit.data?.items.length?'Nenhum evento de auditoria registrado.':undefined}><div className="commercial-audit-list">{audit.data?.items.map(item=><article key={item.id}><span className="commercial-audit-symbol"><History size={17}/></span><div><strong>{item.action}</strong><time dateTime={item.created_at}>{businessDate(item.created_at,undefined,true)}</time><small>Empresa: {item.tenant_id||'Plataforma'} · Usuário: {item.actor_user_id||'Sistema'}</small>{item.entity_type&&<small>{item.entity_type}{item.entity_id?` · ${item.entity_id}`:''}</small>}{Object.keys(item.metadata??{}).length>0&&<details><summary>Ver detalhes do evento</summary><pre>{JSON.stringify(item.metadata,null,2)}</pre></details>}</div></article>)}</div><BusinessPagination page={auditPage} pageSize={audit.data?.pageSize??20} total={audit.data?.total??0} onPage={setAuditPage}/></BusinessState></section>:<BusinessState loading={config.loading} error={config.error} retry={config.refresh}><section className="panel commercial-panel"><div className="commercial-panel-head"><span className="commercial-panel-symbol"><FileText size={24}/></span><div><h2>Identidade e documentos</h2><p>Dados públicos da operação, termos e política de privacidade.</p></div><button className="ghost-btn" onClick={openSettings}>Editar configuração</button></div><dl className="commercial-config-summary"><div><dt>Marca</dt><dd>{config.data?.brand}</dd></div><div><dt>Responsável legal</dt><dd>{config.data?.legal_name||'Não informado'}</dd></div><div><dt>Contato de privacidade</dt><dd>{config.data?.privacy_email||'Não informado'}</dd></div><div><dt>Documentos</dt><dd>{config.data?.published?'Publicados':'Rascunho, ainda não publicado'}</dd></div><div><dt>Plano Free</dt><dd>{config.data?.trial_days} dias de teste</dd></div><div><dt>Tolerância para regularização</dt><dd>{config.data?.grace_days} dias</dd></div></dl><p className="commercial-small-note">Preencha os dados reais e revise os documentos e fornecedores antes de publicar. Salvar um rascunho não solicita aceite dos clientes.</p></section><section className="panel commercial-panel"><div className="commercial-panel-head"><div><h2>Planos e links do PagBank</h2><p>Confira nome, preço, frequência e recorrência na página real de pagamento.</p></div></div><div className="commercial-plan-settings">{config.data?.plans.map(item=><article key={item.id}><span className="commercial-plan-icon"><CreditCard size={23}/></span><div><strong>{item.name}</strong><span>{money(item.amount_cents)} / {item.interval_months===12?'ano':'mês'}</span><small>{item.active===false?'Plano inativo':item.checkout_reviewed?'Link conferido':'Link aguardando conferência'}</small></div><button className="ghost-btn" onClick={()=>editPlan(item)}>Editar plano</button></article>)}</div></section></BusinessState>}
    {dialog&&<FormDialog wide={dialog==='company'||dialog==='settings'} title={dialogTitle} busy={busy} error={error} onClose={close}>
      {dialog==='company'?<BusinessState loading={detail.loading} error={detail.error} retry={detail.refresh}>{current&&<div><div className="commercial-detail-heading"><Label status={current.status}/><span>{current.writable?'Acesso para consulta e alterações':'Acesso somente para consulta'}</span></div><dl className="commercial-detail-metrics"><div><dt>Plano selecionado</dt><dd>{current.plan_name}</dd></div><div><dt>Teste válido até</dt><dd>{businessDate(current.trial_ends_at)}</dd></div><div><dt>Pago até</dt><dd>{businessDate(current.paid_through)}</dd></div></dl>{current.suspension_reason&&<p className="commercial-warning">{current.suspension_reason}</p>}<div className="commercial-detail-actions"><button type="button" className="primary-btn" onClick={openReceipt}><Plus size={17}/>Registrar recebimento</button><button type="button" className="ghost-btn" onClick={openStatus}>{current.status==='suspended'?'Reativar acesso':'Alterar acesso'}</button></div><h3>Histórico de recebimentos</h3><PaymentHistory payments={detail.data?.payments??[]} onVoid={item=>{setPayment(item);reset('void');}}/><div className="form-actions"><button className="ghost-btn" type="button" onClick={close}>Fechar assinatura</button></div></div>}</BusinessState>:dialog==='receipt'?<form className="stack-form commercial-form" onSubmit={save}><button className="text-link" type="button" disabled={busy} onClick={companyBack}><ArrowLeft size={15}/>Voltar para a assinatura</button><label>Plano recebido<select value={receiptPlan} disabled={busy} onChange={event=>setReceiptPlan(event.target.value as typeof receiptPlan)}>{(detail.data?.plans??config.data?.plans??[]).filter(item=>item.active!==false).map(item=><option key={item.id} value={item.id}>{item.name} · {money(item.amount_cents)}</option>)}</select></label><div className="commercial-confirm-value"><span>Valor integral do plano</span><strong>{money(selectedReceiptPlan?.amount_cents??0)}</strong></div><label>Referência da transação no PagBank<input required minLength={3} maxLength={160} disabled={busy} value={reference} onChange={event=>setReference(event.target.value)}/></label><label>Data e horário do recebimento (Brasília)<input required type="datetime-local" disabled={busy} value={receivedAt} onChange={event=>setReceivedAt(event.target.value)}/></label><label className="commercial-check"><input type="checkbox" required disabled={busy} checked={confirmed} onChange={event=>setConfirmed(event.target.checked)}/><span>Conferi no PagBank que o valor deste plano foi recebido.</span></label><p className="commercial-small-note">A confirmação acrescenta o período do plano à validade da assinatura. Não registra uma nova cobrança no cartão.</p>{footer('Confirmar recebimento')}</form>:dialog==='void'?<form className="stack-form commercial-form" onSubmit={save}><p className="commercial-warning">Este procedimento invalida somente o registro no PetCore e recalcula a validade. Um estorno do cartão deve ser realizado no PagBank.</p><label>Motivo<textarea required minLength={5} maxLength={500} disabled={busy} value={reason} onChange={event=>setReason(event.target.value)}/></label><label>Confirme sua senha<input type="password" autoComplete="current-password" required maxLength={200} disabled={busy} value={password} onChange={event=>setPassword(event.target.value)}/></label>{footer('Invalidar registro')}</form>:dialog==='status'?<form className="stack-form commercial-form" onSubmit={save}><label>Situação do acesso<select value={accessStatus} disabled={busy} onChange={event=>setAccessStatus(event.target.value as typeof accessStatus)}><option value="active">Reativar conforme a validade da assinatura</option><option value="suspended">Suspender alterações, preservando consultas</option></select></label><p className="commercial-small-note">Reativar não renova o período pago. Uma assinatura vencida continua somente para consulta até a regularização.</p><label>Motivo<textarea required minLength={5} maxLength={500} disabled={busy} value={reason} onChange={event=>setReason(event.target.value)}/></label><label>Confirme sua senha<input type="password" autoComplete="current-password" required maxLength={200} disabled={busy} value={password} onChange={event=>setPassword(event.target.value)}/></label>{footer('Salvar situação')}</form>:dialog==='settings'?<form className="stack-form commercial-form" onSubmit={save}><div className="commercial-settings-tabs" role="group" aria-label="Seções da configuração">{([['identity','Identificação'],['documents','Documentos'],['providers','Fornecedores'],['access','Acesso']] as const).map(([key,label])=><button type="button" key={key} className={settingsTab===key?'selected':''} aria-pressed={settingsTab===key} onClick={()=>setSettingsTab(key)}>{label}</button>)}</div>
        {settingsTab==='identity'?<><label>Marca comercial<input required minLength={2} maxLength={100} value={draft.brand} disabled={busy} onChange={event=>setDraft({...draft,brand:event.target.value})}/></label><label>Nome ou razão social do responsável<input maxLength={200} value={draft.legal_name} disabled={busy} onChange={event=>setDraft({...draft,legal_name:event.target.value})}/></label><div className="commercial-form-columns"><label>E-mail de suporte<input type="email" maxLength={255} value={draft.support_email} disabled={busy} onChange={event=>setDraft({...draft,support_email:event.target.value})}/></label><label>E-mail para privacidade<input type="email" maxLength={255} value={draft.privacy_email} disabled={busy} onChange={event=>setDraft({...draft,privacy_email:event.target.value})}/></label></div><label>Endereço de contato<textarea maxLength={500} rows={3} value={draft.address} disabled={busy} onChange={event=>setDraft({...draft,address:event.target.value})}/></label></>:settingsTab==='documents'?<><label>Política de Privacidade<textarea className="commercial-document-editor" rows={14} maxLength={40000} value={draft.privacy_text} disabled={busy} onChange={event=>setDraft({...draft,privacy_text:event.target.value})}/></label><label>Termos de Uso<textarea className="commercial-document-editor" rows={14} maxLength={40000} value={draft.terms_text} disabled={busy} onChange={event=>setDraft({...draft,terms_text:event.target.value})}/></label><label>Início da vigência<input type="date" value={draft.effective_date} disabled={busy} onChange={event=>setDraft({...draft,effective_date:event.target.value})}/></label><label className="commercial-check"><input type="checkbox" checked={draft.published} disabled={busy} onChange={event=>setDraft({...draft,published:event.target.checked})}/><span>Publicar esta versão dos documentos</span></label>{draft.published&&<><label className="commercial-check"><input type="checkbox" required checked={review} disabled={busy} onChange={event=>setReview(event.target.checked)}/><span>Conferi os dados reais, os fornecedores e a revisão dos documentos antes da publicação.</span></label><label>Confirme sua senha para publicar<input type="password" required autoComplete="current-password" value={password} maxLength={200} disabled={busy} onChange={event=>setPassword(event.target.value)}/></label></>}<p className="commercial-small-note">A publicação pode exigir novo aceite dos usuários. Mantenha os rascunhos enquanto os dados ou a revisão estiverem pendentes.</p></>:settingsTab==='providers'?<><p className="commercial-small-note">Informe apenas os fornecedores efetivamente utilizados, sua finalidade e onde os dados são tratados.</p>{draft.subprocessors.map((item,index)=><fieldset className="commercial-processor" key={index}><legend>Fornecedor {index+1}</legend><label>Nome<input required minLength={2} maxLength={100} value={item.name} disabled={busy} onChange={event=>updateProcessor(index,'name',event.target.value)}/></label><label>Finalidade<input required minLength={3} maxLength={500} value={item.purpose} disabled={busy} onChange={event=>updateProcessor(index,'purpose',event.target.value)}/></label><label>País / região de tratamento<input required minLength={2} maxLength={200} value={item.location} disabled={busy} onChange={event=>updateProcessor(index,'location',event.target.value)}/></label><button className="text-link commercial-danger-link" type="button" disabled={busy} onClick={()=>setDraft({...draft,subprocessors:draft.subprocessors.filter((_,i)=>i!==index)})}><X size={15}/>Remover fornecedor</button></fieldset>)}<button className="ghost-btn" type="button" disabled={busy||draft.subprocessors.length>=30} onClick={()=>setDraft({...draft,subprocessors:[...draft.subprocessors,{name:'',purpose:'',location:''}]})}><Plus size={16}/>Adicionar fornecedor</button></>:<><label>Duração do Plano Free (dias)<input type="number" required min="0" max="90" step="1" value={draft.trial_days} disabled={busy} onChange={event=>setDraft({...draft,trial_days:event.target.value})}/></label><label>Tolerância após o vencimento (dias)<input type="number" required min="0" max="30" step="1" value={draft.grace_days} disabled={busy} onChange={event=>setDraft({...draft,grace_days:event.target.value})}/></label><p className="commercial-small-note">O período Free vale para novas assinaturas. A tolerância permite regularização antes de limitar as alterações. Consultas, privacidade, suporte e assinatura permanecem disponíveis.</p></>}
        {draft.published&&settingsTab!=='documents'&&<p className="commercial-warning">Esta configuração está publicada. Na aba Documentos, confirme a revisão e sua senha antes de salvar uma alteração.</p>}{footer(draft.published?'Salvar e publicar':'Salvar rascunho')}
      </form>:dialog==='plan'?<form className="stack-form commercial-form" onSubmit={save}><label>Nome do plano<input required minLength={2} maxLength={100} value={planName} disabled={busy} onChange={event=>{setPlanName(event.target.value);setCheckoutReviewed(false);}}/></label><label>Valor integral (R$)<input inputMode="decimal" required value={planAmount} disabled={busy} onChange={event=>{setPlanAmount(event.target.value);setCheckoutReviewed(false);}}/></label><label>Frequência<input readOnly value={plan?.interval_months===12?'Uma cobrança anual':'Uma cobrança mensal'}/></label><label>Link recorrente do PagBank<input type="url" maxLength={1500} value={planUrl} disabled={busy} onChange={event=>{setPlanUrl(event.target.value);setCheckoutReviewed(false);}} placeholder="https://pag.ae/..."/></label>{safeCheckout(planUrl)&&<a className="commercial-external-review" href={safeCheckout(planUrl)!} target="_blank" rel="noopener noreferrer">Abrir link para conferir <ExternalLink size={14}/></a>}<label className="commercial-check"><input type="checkbox" checked={checkoutReviewed} disabled={busy||!planUrl.trim()} onChange={event=>setCheckoutReviewed(event.target.checked)}/><span>Conferi na página do PagBank: nome PetCore, valor, frequência e cobrança recorrente corretos.</span></label><label className="commercial-check"><input type="checkbox" checked={planActive} disabled={busy} onChange={event=>setPlanActive(event.target.checked)}/><span>Plano disponível para seleção</span></label><p className="commercial-small-note">Alterar o preço no PetCore não muda uma assinatura existente no PagBank. Revise o link no provedor antes de disponibilizá-lo.</p>{footer('Salvar plano')}</form>:null}
    </FormDialog>}
  </section>;
}

export function SupportPage({setMessage,setError,platform=false}:BusinessPageProps&{platform?:boolean}){
  const [page,setPage]=useState(1),[selected,setSelected]=useState<Ticket|null>(null),[creating,setCreating]=useState(false),[subject,setSubject]=useState(''),[category,setCategory]=useState('technical'),[body,setBody]=useState(''),[reply,setReply]=useState(''),[status,setStatus]=useState<Ticket['status']>('open'),[busy,setBusy]=useState(false),[error,setLocalError]=useState('');
  const tickets=useBusinessQuery<PageResult<Ticket>>(`/commercial/support?page=${page}&page_size=20`,setError),detail=useBusinessQuery<TicketData>(selected?`/commercial/support/${selected.id}`:null,setError),mounted=useRef(true);
  useEffect(()=>{mounted.current=true;return()=>{mounted.current=false;};},[]);
  function close(){if(!busy){setSelected(null);setCreating(false);setReply('');setLocalError('');}}
  function start(){setSubject('');setCategory('technical');setBody('');setCreating(true);setSelected(null);setLocalError('');}
  function open(item:Ticket){setSelected(item);setCreating(false);setReply('');setStatus(item.status);setLocalError('');}
  async function save(event:FormEvent){event.preventDefault();if(busy)return;setBusy(true);setLocalError('');try{
    if(creating){const ticket=await api<Ticket>('/commercial/support','POST',{subject:subject.trim(),category,body:body.trim()});if(!mounted.current)return;setCreating(false);setSelected(ticket);setStatus(ticket.status);setMessage('Solicitação criada. Acompanhe as respostas por aqui.');}
    else if(selected){await api(`/commercial/support/${selected.id}/messages`,'POST',{body:reply.trim(),...(platform?{status}:{})});if(!mounted.current)return;setReply('');setMessage('Mensagem registrada na solicitação.');detail.refresh();}
    tickets.refresh();
  }catch(cause){if(mounted.current){const text=reasonText(cause);setLocalError(text);setError(text);}}finally{if(mounted.current)setBusy(false);}}
  const ticket=detail.data?.ticket.id===selected?.id?detail.data?.ticket:selected;
  return <div className={`commercial-page commercial-support ${platform?'commercial-support--platform':''}`}>
    {!platform?<PageHeader eyebrow="SUPORTE" title="Como podemos ajudar?" subtitle="Converse com a Tiger Tech e acompanhe suas solicitações." action={<button className="primary-btn" onClick={start}><Plus size={18}/>Nova solicitação</button>}/>:<div className="commercial-section-title"><h2>Atendimento aos pet shops</h2><p>Responda às solicitações e mantenha a situação atualizada.</p></div>}
    <section className="panel commercial-panel"><BusinessState loading={tickets.loading} error={tickets.error} retry={tickets.refresh} empty={!tickets.data?.items.length?(platform?'Nenhuma solicitação de suporte recebida.':'Você ainda não tem solicitações. Abra uma quando precisar de ajuda.'):undefined}><div className="commercial-ticket-list">{tickets.data?.items.map(item=><button key={item.id} onClick={()=>open(item)} aria-label={`Abrir solicitação ${item.subject}`}><span className="commercial-ticket-symbol"><MessageCircle size={20}/></span><span><strong>{item.subject}</strong><small>{platform?`${item.company_name??'Empresa'} · `:''}{categories[item.category]} · {businessDate(item.updated_at,undefined,true)}</small><Label status={item.status}/></span><ChevronRight size={18}/></button>)}</div><BusinessPagination page={page} pageSize={tickets.data?.pageSize??20} total={tickets.data?.total??0} onPage={setPage}/></BusinessState></section><p className="commercial-small-note">As mensagens e respostas ficam registradas nesta área. Não envie senhas, número completo de cartão ou códigos de segurança.</p>
    {(creating||selected)&&<FormDialog wide={!creating} title={creating?'Nova solicitação':selected?.subject??'Solicitação de suporte'} description={creating?'Conte o que aconteceu e como podemos ajudar.':categories[ticket?.category??'other']} busy={busy} error={error} onClose={close}>
      {creating?<form className="stack-form commercial-form" onSubmit={save}><label>Assunto<input required minLength={3} maxLength={160} disabled={busy} value={subject} onChange={event=>setSubject(event.target.value)}/></label><label>Categoria<select value={category} disabled={busy} onChange={event=>setCategory(event.target.value)}>{Object.entries(categories).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label><label>Mensagem<textarea required minLength={5} maxLength={4000} rows={6} disabled={busy} value={body} onChange={event=>setBody(event.target.value)}/></label><div className="form-actions"><button className="ghost-btn" type="button" disabled={busy} onClick={close}>Cancelar</button><button className="primary-btn" type="submit" disabled={busy}>{busy?'Enviando...':'Criar solicitação'}</button></div></form>:<BusinessState loading={detail.loading} error={detail.error} retry={detail.refresh}>{detail.data&&<form className="stack-form commercial-form" onSubmit={save}><div className="commercial-support-detail-top"><Label status={ticket?.status??'open'}/><span>Aberta em {businessDate(ticket?.created_at,undefined,true)}</span></div><div className="commercial-conversation" aria-label="Mensagens da solicitação">{detail.data.messages.map(item=><article key={item.id} className={item.from_platform?'from-platform':'from-company'}><div><strong>{item.from_platform?'Tiger Tech':'Equipe do pet shop'}</strong><time dateTime={item.created_at}>{businessDate(item.created_at,undefined,true)}</time></div><p>{item.body}</p></article>)}</div><p className="commercial-small-note">Exibindo até 200 mensagens, em ordem de envio.</p>{platform&&<label>Situação após a resposta<select value={status} disabled={busy} onChange={event=>setStatus(event.target.value as Ticket['status'])}><option value="open">Aberta</option><option value="in_progress">Em atendimento</option><option value="resolved">Resolvida</option></select></label>}<label>{platform?'Resposta da Tiger Tech':'Adicionar mensagem'}<textarea required minLength={1} maxLength={4000} rows={4} disabled={busy} value={reply} onChange={event=>setReply(event.target.value)}/></label><div className="form-actions"><button className="ghost-btn" type="button" disabled={busy} onClick={close}>Fechar</button><button className="primary-btn" type="submit" disabled={busy||!reply.trim()}>{busy?'Enviando...':'Enviar mensagem'}</button></div></form>}</BusinessState>}
    </FormDialog>}
  </div>;
}

export function TermsConsentDialog({version,onAccepted,onRead,onLogout}:{version:string;onAccepted:()=>void;onRead:(kind:'privacy'|'terms')=>void;onLogout:()=>void}){
  const [legal,setLegal]=useState<Legal|null>(null),[loading,setLoading]=useState(true),[error,setError]=useState(''),[accepted,setAccepted]=useState(false),[busy,setBusy]=useState(false),[revision,setRevision]=useState(0);
  useEffect(()=>{let active=true;setLoading(true);setAccepted(false);api<Legal>('/public/legal').then(data=>{if(active)setLegal(data);}).catch(cause=>{if(active)setError(reasonText(cause));}).finally(()=>{if(active)setLoading(false);});return()=>{active=false;};},[version,revision]);
  async function accept(event:FormEvent){event.preventDefault();if(busy||!accepted||!legal?.published)return;setBusy(true);setError('');try{await api('/commercial/accept-terms','POST',{version:legal.version,accepted:true});onAccepted();}catch(cause){setError(reasonText(cause));setAccepted(false);setRevision(value=>value+1);}finally{setBusy(false);}}
  return <FormDialog title="Termos atualizados" description="Leia os documentos atuais para continuar usando o PetCore." onClose={()=>{}} busy={busy} error={error}>
    <div className="commercial-required-dialog">
    {loading?<Empty label="Carregando documentos..."/>:legal?.published?<form className="stack-form commercial-form commercial-consent" onSubmit={accept}><span className="commercial-consent-symbol"><ShieldCheck size={32}/></span><p>A versão atual dos documentos foi publicada por {legal.operator.brand||'Tiger Tech'}. Consulte os termos e a política antes de confirmar.</p><div className="commercial-legal-links"><button type="button" className="ghost-btn" disabled={busy} onClick={()=>onRead('terms')}><FileText size={18}/>Ler Termos de Uso<ExternalLink size={14}/></button><button type="button" className="ghost-btn" disabled={busy} onClick={()=>onRead('privacy')}><ShieldCheck size={18}/>Ler Política de Privacidade<ExternalLink size={14}/></button></div><small className="commercial-small-note">Versão {legal.version}{legal.effectiveDate?` · Vigência ${businessDate(legal.effectiveDate)}`:''}</small><label className="commercial-check"><input type="checkbox" checked={accepted} disabled={busy} onChange={event=>setAccepted(event.target.checked)}/><span>Li e aceito os Termos de Uso e estou ciente da Política de Privacidade desta versão.</span></label><p className="commercial-small-note">Este aceite não autoriza campanhas de marketing ou lembretes ao tutor. Essas preferências são tratadas separadamente.</p><div className="form-actions"><button type="button" className="ghost-btn" disabled={busy} onClick={onLogout}>Sair da conta</button><button type="submit" className="primary-btn" disabled={busy||!accepted}>{busy?'Registrando...':'Aceitar e continuar'}</button></div></form>:<div className="commercial-consent"><p>Os documentos atuais não estão disponíveis para aceite.</p><button className="ghost-btn" onClick={()=>setRevision(value=>value+1)}>Tentar novamente</button><div className="form-actions"><button className="ghost-btn" onClick={onLogout}>Sair da conta</button></div></div>}
    </div>
  </FormDialog>;
}

export function PlanOnboardingDialog({onDone,onLogout}:{onDone:(plan?:'free'|'monthly'|'yearly')=>void;onLogout:()=>void}){
  const [data,setData]=useState<SubscriptionData|null>(null),[loading,setLoading]=useState(true),[error,setError]=useState(''),[selected,setSelected]=useState<'free'|'monthly'|'yearly'>('free'),[busy,setBusy]=useState(false),[revision,setRevision]=useState(0);
  const [submitted,setSubmitted]=useState<{plan:'monthly'|'yearly';checkout_url:string|null}|null>(null);
  useEffect(()=>{let active=true;setLoading(true);setError('');api<SubscriptionData>('/commercial/me').then(value=>{if(active)setData(value);}).catch(cause=>{if(active)setError(reasonText(cause));}).finally(()=>{if(active)setLoading(false);});return()=>{active=false;};},[revision]);
  async function confirm(event:FormEvent){event.preventDefault();if(busy||!data)return;setBusy(true);setError('');try{const result=await api<{ok:true;plan:'free'|'monthly'|'yearly';checkout_url:string|null}>('/commercial/onboarding','POST',{plan:selected});if(result.plan==='free')onDone('free');else setSubmitted({plan:result.plan,checkout_url:safeCheckout(result.checkout_url)});}catch(cause){setError(reasonText(cause));}finally{setBusy(false);}}
  const days=data?.subscription.trial_days??data?.trialDays??30;
  return <FormDialog wide title="Escolha seu plano PetCore" description="Comece pelo período gratuito ou selecione a assinatura para o seu pet shop." onClose={()=>{}} busy={busy} error={error}>
    <div className="commercial-required-dialog commercial-onboarding">
      {loading?<Empty label="Carregando os planos..."/>:!data?<div className="commercial-consent"><p>Não foi possível carregar os planos disponíveis.</p><button className="ghost-btn" onClick={()=>setRevision(value=>value+1)}>Tentar novamente</button><div className="form-actions"><button className="ghost-btn" onClick={onLogout}>Sair da conta</button></div></div>:submitted?<div className="commercial-onboarding-payment"><span className="commercial-consent-symbol"><CreditCard size={31}/></span><h3>Plano {submitted.plan==='monthly'?'mensal':'anual'} selecionado</h3><p>O pagamento acontece imediatamente no checkout do PagBank. O acesso para cadastrar e alterar informações será liberado após a confirmação do recebimento pela Tiger Tech.</p>{submitted.checkout_url?<a className="primary-btn" href={submitted.checkout_url} target="_blank" rel="noopener noreferrer">Continuar no PagBank <ExternalLink size={17}/></a>:<p className="commercial-warning">O pagamento deste plano está indisponível no momento. Consulte o suporte na área da assinatura.</p>}<p className="commercial-small-note">Selecionar o plano não efetuou cobrança. O pagamento e a autorização de recorrência são concluídos no PagBank, com os dados do cartão informados somente lá.</p><div className="form-actions"><button type="button" className="ghost-btn" onClick={onLogout}>Sair da conta</button><button type="button" className="primary-btn" onClick={()=>onDone(submitted.plan)}>Ver minha assinatura</button></div></div>:<form className="stack-form commercial-form" onSubmit={confirm}>
        <fieldset className="commercial-radio-plans"><legend>Planos disponíveis</legend><label className={`commercial-radio-plan ${selected==='free'?'selected':''}`}><input type="radio" name="onboarding-plan" value="free" checked={selected==='free'} disabled={busy} onChange={()=>setSelected('free')}/><span><strong>Plano Free</strong><b>Grátis</b><small>Por {days} dias, a partir da confirmação.</small><span>Experimente os recursos do PetCore sem cadastrar cartão.</span></span></label>{data.plans.map(item=><label key={item.id} className={`commercial-radio-plan ${selected===item.id?'selected':''}`}><input type="radio" name="onboarding-plan" value={item.id} checked={selected===item.id} disabled={busy} onChange={()=>setSelected(item.id)}/><span><strong>{item.name}</strong><b>{money(item.amount_cents)}<em>/{item.interval_months===12?'ano':'mês'}</em></b><small>{item.interval_months===12?'Pagamento imediato, com recorrência anual':'Pagamento imediato, com recorrência mensal'}</small><span>Pagamento no ambiente seguro do PagBank.</span></span></label>)}</fieldset>
        <p className="commercial-onboarding-note">{selected==='free'?`O Plano Free é um teste de ${days} dias. A contagem começa somente quando você confirmar sua escolha. Ao terminar, não haverá cobrança automática. Para continuar cadastrando e alterando informações, escolha uma assinatura.`:'Você pode assinar agora, sem usar o período Free. O pagamento é imediato no PagBank e o acesso depende da confirmação do recebimento. Selecionar o plano aqui não cobra seu cartão.'}</p>
        <div className="form-actions"><button className="ghost-btn" type="button" disabled={busy} onClick={onLogout}>Sair da conta</button><button className="primary-btn" type="submit" disabled={busy}>{busy?'Confirmando...':selected==='free'?'Começar teste gratuito':'Confirmar escolha'}</button></div>
      </form>}
    </div>
  </FormDialog>;
}
